// `fill: undefined` means the path takes the caller's `color`; a concrete value
// is a fixed brand colour that ignores it.

export type FillRule = "evenodd" | "nonzero";

export interface IconPath {
  d: string;
  fill?: string;
  opacity?: number;
  fillRule?: FillRule;
  clipRule?: FillRule;
  // Strokes the filled outline in its own colour, thickening every edge by half this on each side.
  strokeWidth?: number;
  // Draws the path as an unfilled line of this width with round caps and joins.
  lineWidth?: number;
}

export interface IconGeometry {
  viewBox: string;
  paths: readonly IconPath[];
}

